import{c as a,S as t,j as o,m as i}from"./chunks/framework.VsSDrsS3.js";const g=JSON.parse('{"title":"微信小程序 & 企微开发","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge/wechat/miniprogram-tips.md","filePath":"knowledge/wechat/miniprogram-tips.md","lastUpdated":1780046787000}'),r={name:"knowledge/wechat/miniprogram-tips.md"};function d(l,e,n,c,s,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="微信小程序-企微开发" tabindex="-1">微信小程序 &amp; 企微开发 <a class="header-anchor" href="#微信小程序-企微开发" aria-label="Permalink to “微信小程序 &amp; 企微开发”">​</a></h1><h2 id="订阅消息" tabindex="-1">订阅消息 <a class="header-anchor" href="#订阅消息" aria-label="Permalink to “订阅消息”">​</a></h2><p><strong>问题：</strong> 用户勾选&quot;总保持以上选择，不再询问&quot;后，订阅消息弹窗永久消失。</p><p><strong>知识点：</strong></p><ul><li><code>wx.requestSubscribeMessage</code> 被拒绝后，<strong>程序无法自动再次触发弹窗</strong>。但用户可手动进入小程序设置（<code>wx.openSetting</code>）重新开启订阅开关</li><li>解决方案：引导用户去小程序设置页 <code>wx.openSetting</code> 手动打开订阅开关</li><li>最佳实践：<strong>只在必要时请求</strong>，避免用户反感后一次性拒绝所有</li></ul><h2 id="url-scheme-生成" tabindex="-1">URL Scheme 生成 <a class="header-anchor" href="#url-scheme-生成" aria-label="Permalink to “URL Scheme 生成”">​</a></h2><p><strong>知识点：</strong></p><ul><li><code>wx.urlscheme.generate</code> 可从服务端生成小程序跳转链接</li><li>适用于短信、邮件、H5 等外部场景拉起小程序</li><li>每天生成上限 10 万条，有效期 30 天</li><li>URL Scheme 可携带自定义参数（path + query）</li></ul><h2 id="长按识别二维码" tabindex="-1">长按识别二维码 <a class="header-anchor" href="#长按识别二维码" aria-label="Permalink to “长按识别二维码”">​</a></h2><p><strong>知识点：</strong> 小程序已支持 <code>image</code> 组件的 <code>show-menu-by-longpress</code> 属性，长按图片可识别其中二维码。需基础库 2.7.0+。</p><h2 id="nfc-标签打开小程序" tabindex="-1">NFC 标签打开小程序 <a class="header-anchor" href="#nfc-标签打开小程序" aria-label="Permalink to “NFC 标签打开小程序”">​</a></h2><p><strong>知识点：</strong> 小程序支持通过 NFC 标签的 URL Scheme 打开。需在 NFC 标签中写入 <code>https://wxapp.tc.qq.com/xxx</code> 格式的链接。</p><h2 id="自定义相机" tabindex="-1">自定义相机 <a class="header-anchor" href="#自定义相机" aria-label="Permalink to “自定义相机”">​</a></h2><p><strong>避坑：</strong></p><ul><li><code>CameraContext.takePhoto</code> 获取的照片质量偏低，需设置 <code>quality: &#39;high&#39;</code></li><li>自定义取景框需手动计算位置，注意屏幕比例适配</li><li>保存到本地相册需 <code>wx.saveImageToPhotosAlbum</code> 权限（writePhotosAlbum）</li><li>GPS 定位需 <code>wx.getLocation</code> 权限，且需在 <code>app.json</code> 中声明 <code>requiredPrivateInfos</code></li></ul><h2 id="滚动穿透" tabindex="-1">滚动穿透 <a class="header-anchor" href="#滚动穿透" aria-label="Permalink to “滚动穿透”">​</a></h2><p><strong>问题：</strong> 弹出蒙层后，背景页面仍可滚动。</p><p><strong>知识点：</strong></p><ul><li>旧方案 <code>catchtouchmove</code> 在 WebView 下有效，但 Skyline 渲染引擎下无效</li><li>推荐方案：在蒙层 <code>view</code> 上使用 <code>catch:touchmove=&quot;true&quot;</code>（注意冒号写法）</li><li>或在组件 <code>page-meta</code> 中设置 <code>page-style=&quot;overflow: hidden;&quot;</code></li><li>Skyline 渲染引擎本身已禁止页面滚动，需用 <code>scroll-view</code> 包裹可滚动区域</li></ul><h2 id="ios-端图片-exif-信息丢失" tabindex="-1">iOS 端图片 EXIF 信息丢失 <a class="header-anchor" href="#ios-端图片-exif-信息丢失" aria-label="Permalink to “iOS 端图片 EXIF 信息丢失”">​</a></h2><p><strong>问题：</strong> iOS 上传图片时会自动压缩并丢弃 EXIF（GPS、方向等元数据）。</p><p><strong>知识点：</strong></p><ul><li><code>wx.chooseImage</code> 的 <code>sizeType: [&#39;original&#39;]</code> 可保留原图</li><li><code>wx.chooseMedia</code> + <code>sizeType: [&#39;original&#39;]</code> 在真机上可能仍丢失经纬度（微信 8.0.27 已知 Bug）</li><li>替代方案：使用 <code>wx.chooseMessageFile</code> 从聊天记录选文件，或引导用户从相册原图模式选取</li><li>压缩时保留 EXIF：使用 <code>exif-js</code> + 自定义 Canvas 绘制方案</li></ul><h2 id="页面间数据传递" tabindex="-1">页面间数据传递 <a class="header-anchor" href="#页面间数据传递" aria-label="Permalink to “页面间数据传递”">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>场景</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>URL 参数 + onLoad</td><td>少数据量跳转</td><td>简单</td><td>URL 有长度限制（~2KB），对象需 JSON+encode</td></tr><tr><td>getApp().globalData</td><td>全局共享状态</td><td>跨多页</td><td>非响应式，页面销毁后数据仍残留</td></tr><tr><td>事件总线（EventEmitter）</td><td>复杂数据流</td><td>解耦</td><td>需手动清理 listener，防泄漏</td></tr><tr><td>wx.setStorageSync</td><td>持久化数据</td><td>可靠</td><td>同步 IO，大数据量影响性能</td></tr></tbody></table><p>综合推荐：少量数据用 URL 传参，全局状态用 globalData，持久化用 storage。</p><h2 id="小程序插件开发" tabindex="-1">小程序插件开发 <a class="header-anchor" href="#小程序插件开发" aria-label="Permalink to “小程序插件开发”">​</a></h2><p>插件独立于宿主小程序，有独立 AppID。插件页面不能直接跳宿主（需通过 <code>plugin-private://</code> 协议），开发时需在开发者工具中单独创建插件项目。uni-app 开发插件也需独立项目，不能与主项目混用。</p><blockquote><p>📝 插件开发涉及权限申请、版本管理、功能页配置等多个环节，详见 <a href="https://developers.weixin.qq.com/miniprogram/dev/framework/plugin/" target="_blank" rel="noreferrer">微信官方文档</a>。</p></blockquote><h2 id="小程序重启-强制更新" tabindex="-1">小程序重启 &amp; 强制更新 <a class="header-anchor" href="#小程序重启-强制更新" aria-label="Permalink to “小程序重启 &amp; 强制更新”">​</a></h2><ul><li>重启：wx.restartMiniProgram({ path: &#39;/pages/index/index&#39; })</li><li>强制更新：updateManager.onUpdateReady() 监听，弹窗引导重启</li><li>__wxConfig.envVersion 获取当前环境（develop/trial/release）</li></ul>',31)])])}const m=a(r,[["render",d]]);export{g as __pageData,m as default};
